def key_normalize(key: str) -> str:
    key = unicodedata.normalize("NFKD", str(key).lower())
    key = "".join(c for c in key if not unicodedata.combining(c))
    return re.sub(r"[^a-z0-9_]", "", key)


def parse_line(text: str) -> dict[str, float] | None:
    """Acepta JSON, valores clave=valor o CSV: ph,ec,tds,temp."""
    text = text.strip()
    if not text:
        return None
    raw: dict[str, object] = {}
    if text.startswith("{"):
        try:
            obj = json.loads(text)
            if not isinstance(obj, dict):
                return None
            raw = obj
        except (ValueError, TypeError):
            return None
    elif ":" in text or "=" in text:
        for item in re.split(r"[,;|]", text):
            pair = re.split(r"\s*[:=]\s*", item, maxsplit=1)
            if len(pair) == 2:
                raw[pair[0].strip()] = pair[1].strip()
    else:
        values = [x.strip() for x in re.split(r"[,;]", text)]
        if len(values) == 4:
            raw = dict(zip(("ph", "ec", "tds", "temp"), values))

    out: dict[str, float] = {}
    for input_key, input_value in raw.items():
        target = ALIASES.get(key_normalize(input_key))
        if not target:
            continue
        try:
            value = float(input_value)
        except (ValueError, TypeError):
            continue
        if math.isfinite(value):
            out[target] = value

    # Sólo se guardan líneas COMPLETAS: nunca mezclar muestras de tiempos diferentes.
    if set(out) != set(PARAMS):
        return None
    if not (0 <= out["ph"] <= 14 and -30 <= out["temp"] <= 125
            and 0 <= out["ec"] <= 100000 and 0 <= out["tds"] <= 100000):
        return None
    return out


def add_record(values: dict[str, float], source: str, dt: datetime | None = None) -> None:
    row = {"hora": dt or datetime.now(), **values, "origen": source}
    st.session_state.records.append(row)
    st.session_state.sample_count += 1
    limit = st.session_state.max_records
    if len(st.session_state.records) > limit:
        del st.session_state.records[:-limit]


def demo_values(i: int) -> dict[str, float]:
    return {
        "ph": round(7.20 + .10 * math.sin(i * .22) + .025 * math.sin(i * .8), 2),
        "temp": round(24.5 + .34 * math.sin(i * .07), 1),
        "ec": round(520 + 14 * math.sin(i * .16)),
        "tds": round(310 + 8 * math.sin(i * .16)),
    }


def fill_demo_initial() -> None:
    if st.session_state.records:
        return
    now = datetime.now()
    for i in range(61):
        add_record(demo_values(i), "DEMO", now - timedelta(seconds=(60-i)*10))
    st.session_state.demo_tick = 61


def close_serial() -> None:
    conn = st.session_state.serial_connection
    if conn is not None:
        try:
            if conn.is_open:
                conn.close()
        except (serial.SerialException, OSError):
            pass
    st.session_state.serial_connection = None
    st.session_state.serial_buffer = ""


def open_serial(port: str, baud: int) -> None:
    close_serial()
    if not port:
        st.session_state.serial_error = "Selecciona un puerto o escríbelo manualmente."
        return
    try:
        conn = serial.Serial(port=port, baudrate=baud, timeout=0)
        conn.reset_input_buffer()
        st.session_state.serial_connection = conn
        st.session_state.serial_port = port
        st.session_state.serial_error = ""
        st.session_state.records = []
        st.session_state.sample_count = 0
        st.session_state.invalid_lines = 0
        st.session_state.mode = "SERIAL"
    except (serial.SerialException, OSError, ValueError) as exc:
        st.session_state.serial_error = f"No fue posible abrir {port}: {exc}"
        st.session_state.mode = "DEMO"


def poll_data() -> None:
    """Se llama cada segundo desde st.fragment. Sin threads ni bloqueo de la UI."""
    if st.session_state.mode == "DEMO":
        fill_demo_initial()
        i = st.session_state.demo_tick
        add_record(demo_values(i), "DEMO")
        st.session_state.demo_tick = i + 1
        return

    ser = st.session_state.serial_connection
    if ser is None:
        return
    try:
        count = min(ser.in_waiting, 16384)
        if count < 1:
            return
        chunk = ser.read(count).decode("utf-8", errors="ignore")
        buffer = st.session_state.serial_buffer + chunk
        parts = re.split(r"\r\n|\n|\r", buffer)
        st.session_state.serial_buffer = parts.pop()[-4096:]
        for line in parts[-200:]:
            line = line.strip()
            if not line:
                continue
            st.session_state.last_raw_line = line[:200]
            reading = parse_line(line)
            if reading is None:
                st.session_state.invalid_lines += 1
            else:
                add_record(reading, "SERIAL")
    except (serial.SerialException, OSError) as exc:
        st.session_state.serial_error = f"Se perdió la conexión serial: {exc}"
        close_serial()
        st.session_state.mode = "DESCONECTADO"


def latest_values() -> dict[str, float] | None:
    if not st.session_state.records:
        return None
    return st.session_state.records[-1]


def format_value(key: str, value: float | None) -> str:
    if value is None:
        return "—"
    if key == "ph":
        return f"{value:.2f}"
    if key == "temp":
        return f"{value:.1f}"
    return f"{value:,.0f}"


def status_for(key: str, value: float | None) -> tuple[str, str]:
    if value is None:
        return "Sin lectura", "none"
    low, high = st.session_state.thresholds[key]
    return ("En rango", "ok") if low <= value <= high else ("Revisar", "warn")


def cards_html(row: dict | None) -> str:
    result = ['<div class="reading-grid">']
    for key, meta in PARAMS.items():
        value = row.get(key) if row else None
        label, level = status_for(key, value)
        low, high = meta["scale"]
        fraction = (value - low)/(high-low) if value is not None else 0
        pct = max(0, min(100, fraction * 100))
        result.append(f'''<div class="reading-card" style="--cardcolor:{meta['color']}">
            <div class="card-top">
                <div class="sensor-icon">{html.escape(meta['icon'])}</div>
                <div><div class="reading-title">{html.escape(meta['title'])}</div>
                    <div class="reading-value">{format_value(key,value)} <span class="reading-unit">{meta['unit']}</span></div></div>
            </div>
            <span class="state-label state-{level}">{'● ' + label}</span>
            <div class="bar"><span class="marker" style="left:{pct:.2f}%"></span></div>
            <div class="bar-labels"><span>{low:g}</span><span>{high:g} {meta['unit']}</span></div>
        </div>''')
    return "".join(result) + "</div>"


def summary_html(row: dict | None) -> str:
    if row is None:
        mode, text, subtitle, icon = "empty", "Sin lecturas", "Conecta el Arduino o activa DEMO.", "?"
    else:
        outside = [p for p in PARAMS if status_for(p, row[p])[1] == "warn"]
        if outside:
            mode, text, subtitle, icon = "alert", "Revisar valores", "Fuera de los umbrales configurados: " + ", ".join(PARAMS[x]['title'] for x in outside), "!"
        else:
            mode, text, subtitle, icon = "", "Lecturas en rango", "Los cuatro parámetros cumplen los límites configurados para esta demostración.", "✓"
    return (f'<div class="mini-info"><h4>🛡️ Estado general</h4>'
            f'<div class="ok-panel {mode}"><span class="ok-symbol">{icon}</span>'
            f'<div><div class="ok-title">{html.escape(text)}</div>'
            f'<div class="ok-subtitle">{html.escape(subtitle)}</div></div></div></div>')


def dataframe() -> pd.DataFrame:
    return pd.DataFrame.from_records(st.session_state.records)


def graph(df: pd.DataFrame, key: str = "ph", height: int = 274) -> go.Figure:
    metadata = PARAMS[key]
    fig = go.Figure()
    if not df.empty:
        view = df.tail(150)
        fig.add_trace(go.Scatter(
            x=view["hora"], y=view[key], mode="lines+markers", name=metadata["title"],
            line=dict(color="#168ce2", width=2.9, shape="spline", smoothing=.5),
            marker=dict(color="#168ce2", size=4.5),
            fill="tozeroy", fillcolor="rgba(43,157,231,0.09)",
            hovertemplate="%{x|%H:%M:%S}<br>%{y:.2f} " + metadata["unit"] + "<extra></extra>",
        ))
    fig.update_layout(
        margin=dict(l=12,r=10,t=5,b=12),height=height,
        paper_bgcolor="#ffffff",plot_bgcolor="#ffffff",showlegend=False,
        font=dict(color="#527589",size=11),
        xaxis=dict(gridcolor="#e8f2f7",tickformat="%H:%M",showline=False,zeroline=False),
        yaxis=dict(gridcolor="#e8f2f7",zeroline=False,title=metadata["unit"] or "pH",tickfont=dict(size=10)),
    )
    return fig


def show_header() -> None:
    mode = st.session_state.mode
    if mode == "SERIAL" and st.session_state.serial_connection is not None:
        mode_text = "SERIAL · " + html.escape(st.session_state.serial_port)
        desc = "Recibiendo datos por USB / serial"
    elif mode == "DEMO":
        mode_text = "DEMO"
        desc = "Datos simulados — sin conexión al Arduino"
    else:
        mode_text = "DESCONECTADO"
        desc = "No hay conexión serial"
    st.markdown(f'''<div class="hero-head">
        <img alt="AURAmbient - Sistema multiparámetro de agua" src="data:image/png;base64,{LOGO_B64}" />
        <div class="header-right"><span class="pill"><span class="live-dot"></span>{mode_text}</span>
        <span class="pill">📡 {html.escape(desc)}</span></div></div>''',unsafe_allow_html=True)


def show_home() -> None:
    row = latest_values()
    st.markdown('''<div class="caption-hero"><h1>💧 Calidad del agua</h1>
                <p>Visualización de parámetros en tiempo real</p></div>''',unsafe_allow_html=True)
    st.markdown(cards_html(row), unsafe_allow_html=True)
    left, right = st.columns([2.4,1.0],gap="medium")
    with left:
        st.markdown('<div class="section-heading">📊 Historial de mediciones</div>',unsafe_allow_html=True)
        df = dataframe()
        st.plotly_chart(graph(df,"ph"),use_container_width=True,config={"displayModeBar":False},key="home_graph")
    with right:
        st.markdown(summary_html(row),unsafe_allow_html=True)
        st.markdown('<div class="status-strip">Los límites mostrados son configurables, no certifican potabilidad del agua.</div>',unsafe_allow_html=True)
    if row:
        secs = max(0, int((datetime.now()-row['hora']).total_seconds()))
        st.markdown(f'<div class="status-strip">Última muestra: hace {secs} s · Registros en memoria: {len(st.session_state.records)} · Fuente: {html.escape(row["origen"])}</div>',unsafe_allow_html=True)
    else:
        st.info("Aún no hay datos válidos. Comprueba el formato enviado por Arduino en Ajustes.")


def show_history() -> None:
    st.markdown('''<div class="caption-hero"><h1>📈 Historial de mediciones</h1>
                <p>Selecciona una variable y consulta su evolución.</p></div>''',unsafe_allow_html=True)
    a, b = st.columns([2,1])
    with a:
        selected = st.selectbox("Parámetro",list(PARAMS),format_func=lambda x: PARAMS[x]["title"],key="history_var")
    with b:
        window = st.selectbox("Periodo",["Últimos 10 min","Última hora","24 horas","Todos"],index=1,key="history_window")
    df = dataframe()
    if not df.empty and window != "Todos":
        delta = {"Últimos 10 min":timedelta(minutes=10),"Última hora":timedelta(hours=1),"24 horas":timedelta(days=1)}[window]
        df = df[df["hora"] >= datetime.now()-delta]
    st.plotly_chart(graph(df,selected,340),use_container_width=True,config={"displayModeBar":False},key="hist_graph")
    if not df.empty:
        values = df[selected]
        c1,c2,c3,c4 = st.columns(4)
        c1.metric("Actual",f"{format_value(selected,values.iloc[-1])} {PARAMS[selected]['unit']}")
        c2.metric("Mínimo",f"{values.min():.2f}")
        c3.metric("Máximo",f"{values.max():.2f}")
        c4.metric("Promedio",f"{values.mean():.2f}")
        data_csv = df.copy()
        data_csv["hora"] = data_csv["hora"].dt.strftime("%Y-%m-%d %H:%M:%S")
        st.download_button("⬇️ Descargar historial CSV", data_csv.to_csv(index=False).encode("utf-8-sig"),"AURAmbient_historial.csv","text/csv",use_container_width=True)
    else:
        st.info("No existen mediciones en el periodo seleccionado.")


def show_calibration() -> None:
    st.markdown('''<div class="caption-hero"><h1>🎯 Calibración</h1>
                <p>Guía de verificación de sensores.</p></div>''',unsafe_allow_html=True)
    st.warning("Esta sección es informativa. No envía comandos de calibración al Arduino; esa función requiere programación específica para cada sensor.")
    a,b=st.columns(2,gap="large")
    with a:
        st.markdown("### Sensor de pH")
        st.write("Utiliza soluciones buffer recomendadas por el fabricante (por ejemplo, pH 4, 7 y 10). Enjuaga la sonda entre soluciones y espera a que la lectura se estabilice.")
        st.markdown("### Conductividad (EC)")
        st.write("Emplea un estándar apropiado al rango de trabajo, por ejemplo 1413 µS/cm si lo indica el fabricante. Considera compensación por temperatura.")
    with b:
        st.markdown("### Sólidos disueltos (TDS)")
        st.write("Verifica si el valor TDS procede de un sensor específico o de la conductividad mediante un factor de conversión. No asumas que ambos son mediciones independientes.")
        st.markdown("### Temperatura")
        st.write("Compara la lectura con un termómetro de referencia dentro del rango esperado y registra cualquier desviación.")
    st.info("Cuando conozcas la marca/modelo de los sensores y sus instrucciones, podrás implementar aquí la calibración real.")


def show_settings() -> None:
    st.markdown('''<div class="caption-hero"><h1>⚙️ Ajustes y conexión serial</h1>
                <p>Configura la lectura desde el Arduino conectado a esta computadora.</p></div>''',unsafe_allow_html=True)
    left,right=st.columns([1.15,1],gap="large")
    with left:
        st.markdown("### 🔌 Puerto serial")
        discovered = sorted((p.device, p.description) for p in list_ports.comports())
        options = ["Seleccionar puerto..."] + [p[0] for p in discovered]
        port_sel = st.selectbox("Puerto detectado", options, key="selected_port")
        desc = dict(discovered).get(port_sel)
        if desc:
            st.caption(desc)
        manual = st.text_input("O escribe un puerto manualmente",placeholder="Ej. COM3 o /dev/ttyACM0",key="manual_port")
        baud = st.selectbox("Velocidad en baudios (baud rate)",[9600,19200,38400,57600,115200],index=0,key="serial_baud")
        port = manual.strip() or (port_sel if port_sel != options[0] else "")
        x,y=st.columns(2)
        with x:
            if st.button("🔗 Conectar Arduino",type="primary",use_container_width=True):
                open_serial(port,baud)
                st.rerun()
        with y:
            if st.button("⏹️ Desconectar",use_container_width=True):
                close_serial()
                st.session_state.mode = "DESCONECTADO"
                st.session_state.serial_error = ""
                st.rerun()
        if st.button("▶️ Usar datos DEMO",use_container_width=True):
            close_serial()
            st.session_state.mode = "DEMO"
            st.session_state.serial_error = ""
            st.session_state.records = []
            st.session_state.sample_count = 0
            st.rerun()
        if st.session_state.serial_error:
            st.error(st.session_state.serial_error)
        st.caption("Si Arduino está conectado por USB, primero cierra el Monitor Serial del IDE para liberar el puerto.")
        st.markdown("**Última línea recibida:**")
        st.code(st.session_state.last_raw_line or "(Todavía no se recibió ninguna línea)",language="text")
        st.caption(f"Líneas no válidas: {st.session_state.invalid_lines}")
    with right:
        st.markdown("### 📏 Umbrales de monitoreo")
        st.caption("Ejemplos de configuración interna; no son normas universales ni certifican que el agua sea potable.")
        limits = {}
        for k,meta in PARAMS.items():
            lower,upper = st.session_state.thresholds[k]
            l,r=st.columns(2)
            with l:
                low = st.number_input(f"{meta['title']} mínimo",value=float(lower),key=f"th_{k}_min")
            with r:
                high = st.number_input(f"{meta['title']} máximo",value=float(upper),key=f"th_{k}_max")
            limits[k]=(low,high)
        if st.button("💾 Guardar umbrales",type="primary",use_container_width=True):
            if any(lo >= hi for lo,hi in limits.values()):
                st.error("Cada mínimo debe ser menor que su máximo.")
            else:
                st.session_state.thresholds=limits
                st.success("Umbrales guardados en esta sesión.")
        st.markdown("### 📨 Formato de los datos")
        st.code('{"ph":7.20,"ec":520,"tds":310,"temp":24.5}',language="json")
        st.code('pH:7.20,EC:520,TDS:310,Temp:24.5\n7.20,520,310,24.5',language="text")
        st.caption("Una muestra completa por línea, terminada en salto de línea (\\n). Conductividad en µS/cm, TDS en ppm, temperatura en °C.")
        if st.button("🧹 Borrar historial de esta sesión",use_container_width=True):
            st.session_state.records = []
            st.session_state.sample_count = 0
            st.rerun()


@st.fragment(run_every="1s")
def auto_update_panel() -> None:
    poll_data()
    show_header()
    page=st.session_state.page
    if page == "Inicio":
        show_home()
    elif page == "Historial":
        show_history()
    elif page == "Calibración":
        show_calibration()


# En Ajustes no se hace polling, para evitar interrumpir los campos de entrada.
if st.session_state.page == "Ajustes":
    show_header()
    show_settings()
else:
    auto_update_panel()

st.markdown('<div class="nav-wrap"></div>',unsafe_allow_html=True)
nav_labels = ["🏠 Inicio","📊 Historial","🎯 Calibración","⚙️ Ajustes"]
pages=["Inicio","Historial","Calibración","Ajustes"]
cols=st.columns(4,gap="small")
for col, page, label in zip(cols,pages,nav_labels):
    with col:
        if st.button(label,type="primary" if st.session_state.page==page else "secondary",use_container_width=True,key=f"nav_{page}"):
            st.session_state.page=page
            st.rerun()

st.caption("AURAmbient · Panel experimental. Las lecturas DEMO son simuladas y los estados dependen de los umbrales definidos por el usuario.")

